from pathlib import Path
p=Path('/home/ubuntu/clipforge/app/page.tsx')
s=p.read_text()
s=s.replace("const [url,setUrl]=useState(''); const [brief,setBrief]=useState('');", "const [url,setUrl]=useState(''); const [file,setFile]=useState<File|null>(null); const [brief,setBrief]=useState('');")
s=s.replace("const run=async()=>{if(!url.trim())return;setBusy(true);setNotice('');setStage(0);try{const r=await fetch('/api/process',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({url,brief,clipCount:count})});", "const run=async()=>{if(!url.trim()&&!file)return;setBusy(true);setNotice('');setStage(0);try{const body=file?(()=>{const f=new FormData();f.append('file',file);f.append('brief',brief);f.append('clipCount',String(count));return f})():JSON.stringify({url,brief,clipCount:count});const r=await fetch('/api/process',{method:'POST',...(file?{}:{headers:{'content-type':'application/json'}}),body});")
s=s.replace('<button className="flex w-full items-center justify-center gap-2 rounded-2xl border border-dashed border-ink/25 px-4 py-4 text-sm font-semibold transition hover:border-coral hover:bg-coral/5"><Upload size={16}/> Upload a video file <span className="text-xs font-normal opacity-50">(local worker)</span></button>', '<label htmlFor="video-file" className="flex w-full cursor-pointer items-center justify-center gap-2 rounded-2xl border border-dashed border-ink/25 px-4 py-4 text-sm font-semibold transition hover:border-coral hover:bg-coral/5"><Upload size={16}/> {file?file.name:"Upload a video file"} <span className="text-xs font-normal opacity-50">(MP4, MOV, WebM, MKV)</span><input id="video-file" type="file" accept="video/mp4,video/quicktime,video/webm,video/x-matroska" className="hidden" onChange={e=>setFile(e.target.files?.[0]||null)}/></label>')
s=s.replace('disabled={busy||!url.trim()}', 'disabled={busy||(!url.trim()&&!file)}')
p.write_text(s)
